#include "rinkfit/event_io.hpp"
#include <iostream>
int main(int argc,char**argv){using namespace rinkfit::eventio;if(argc!=2)return 2;const std::filesystem::path p=argv[1];auto write=[&](const char*s){std::ofstream f(p,std::ios::binary|std::ios::trunc);f<<s;};write("abc");const auto a=file_sha256(p);verify(p,a);verify(p,a);if(verification_statistics().at("unchanged_file_reuses")!=1)throw std::runtime_error("no unchanged-file reuse");bool rejected=false;try{verify(p,std::string(64,'0'));}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("cached digest accepted wrong proof");Json descriptor={{"file",p.u8string()},{"sha256",a},{"dtype","|u1"},{"shape",{3}}};auto data=read_array<std::uint8_t>({},descriptor,"|u1");if(data!=std::vector<std::uint8_t>{'a','b','c'})throw std::runtime_error("cached array bytes changed");auto bad=descriptor;bad["sha256"]=std::string(64,'0');rejected=false;try{read_array<std::uint8_t>({},bad,"|u1");}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("array reader accepted wrong cached digest");const auto old=std::filesystem::last_write_time(p);write("abd");std::filesystem::last_write_time(p,old+std::chrono::seconds(1));rejected=false;try{verify(p,a);}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("same-size changed input escaped verification");rejected=false;try{read_array<std::uint8_t>({},descriptor,"|u1");}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("array reader accepted same-size changed file");descriptor["sha256"]=file_sha256(p);data=read_array<std::uint8_t>({},descriptor,"|u1");if(data!=std::vector<std::uint8_t>{'a','b','d'})throw std::runtime_error("changed array bytes");verify(p,file_sha256(p));std::cout<<verification_statistics().dump()<<'\n'<<"verified input memo tests passed\n";}
